import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter applied to the customer list.
 *
 * @param name      free text; every whitespace-separated term must appear, case-
 *                  and accent-insensitively, as a substring of the customer's
 *                  first name or last name. Blank matches every customer.
 * @param statuses  statuses to keep; empty matches every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern MARKS = Pattern.compile("\\p{M}");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether the given customer satisfies both the name and the status filter. */
    public boolean matches(Customer customer) {
        return matchesStatus(customer) && matchesName(customer);
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private boolean matchesName(Customer customer) {
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    private List<String> nameTerms() {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return WHITESPACE.splitAsStream(trimmed).map(CustomerFilter::normalize).toList();
    }

    private static String normalize(String s) {
        String decomposed = Normalizer.normalize(s, Normalizer.Form.NFD);
        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
