import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.example.customers.domain.QueryLog;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
import org.vaadin.addons.dramafinder.element.GridElement;
import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;

/**
 * Drives the real, rendered view in a headless Chromium browser via
 * Playwright/Drama Finder -- the only way to observe what the address bar
 * actually shows and how many requests typing sends to the backend.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port;
    }

    @Test
    void typingDebouncesAndUpdatesAddressBar() {
        Page page = getPage();

        queryLog.clear();
        Locator nameInput = page.getByPlaceholder("Filter by name");
        nameInput.pressSequentially("Aaltonen", new Locator.PressSequentiallyOptions().setDelay(30));
        page.waitForTimeout(600);

        assertTrue(queryLog.pageQueries().size() <= 2,
                "Typing a 8-letter name cost " + queryLog.pageQueries().size()
                        + " backend page queries; it must cost one or two, not one per keystroke");

        GridElement grid = GridElement.get(page);
        assertTrue(grid.getTotalRowCount() > 0 && grid.getTotalRowCount() < 500);
        assertTrue(page.url().contains("name=Aaltonen"), "Address bar was " + page.url());

        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
        statusFilter.selectItem("ACTIVE");
        page.waitForTimeout(300);
        assertTrue(page.url().contains("status=ACTIVE"), "Address bar was " + page.url());

        nameInput.fill("");
        page.waitForTimeout(600);
        assertTrue(!page.url().contains("name="), "Address bar was " + page.url());
    }

    @Test
    void openingUrlWithParametersAppliesFilterInBrowser() {
        Page page = getPage();
        page.navigate(getUrl() + "/?name=Aaltonen&status=ACTIVE");
        page.waitForTimeout(300);

        Locator nameInput = page.getByPlaceholder("Filter by name");
        assertEquals("Aaltonen", nameInput.inputValue());

        GridElement grid = GridElement.get(page);
        assertTrue(grid.getTotalRowCount() > 0 && grid.getTotalRowCount() < 500);
    }
}
